from pathlib import Path
import base64, html, re

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'docs' / 'presentacion'
OUT.mkdir(parents=True, exist_ok=True)
java = (ROOT/'java-swing/src/main/java/com/ejemplo/monitor/MonitorSensoresApp.java').read_text(encoding='utf-8')
slides=[]
def esc(s): return html.escape(s)
def p(s): return '<p>'+s+'</p>'
def bullets(*items): return '<ul>'+''.join('<li>'+s+'</li>' for s in items)+'</ul>'
def code(s): return '<pre><code>'+esc(s.strip())+'</code></pre>'
def snippet(start,end): return java[java.index(start):java.index(end,java.index(start))].rstrip()
def image(name,alt):
    f=ROOT/'docs/montaje'/name
    return '<img alt="'+esc(alt)+'" src="data:image/png;base64,'+base64.b64encode(f.read_bytes()).decode()+'">'
def add(title,body,notes,section='JAVA',cls=''):
    slides.append((title,body,notes,section,cls))
def cols(a,b): return '<div class="cols"><div>'+a+'</div><div>'+b+'</div></div>'

add('Monitor multisensor\ncon ESP32 y Java',p('Circuito, comunicación e interfaz gráfica')+p('<strong>Java Swing como centro de la aplicación</strong>')+p('DS18x20 · MPU-6050 · HC-SR04 · pulsador'), 'Presentar el objetivo: adquirir medidas del circuito y convertirlas en información visible mediante una aplicación Java. El firmware del ESP32 está escrito en C++, mientras que el programa de escritorio está escrito en Java. No se mide humedad.', 'PROYECTO','cover')
add('Qué hace el sistema',cols(bullets('El ESP32 toma temperatura, distancia, aceleración X/Y/Z y estado del pulsador.','El firmware envía una muestra de texto aproximadamente cada segundo.','Java recibe la muestra, comprueba su formato y actualiza las etiquetas Swing.'),p('<span class="big">6</span><br>valores recibidos en cada muestra')+p('Una misma interfaz admite USB real y simulación Wokwi.')), 'Explicar la separación de responsabilidades. El MPU-6050 dispone de más capacidades, pero este programa transmite solo aceleración. El puente Python es necesario para la ruta del simulador, no para USB real.', 'PROYECTO')
add('Conexiones del circuito',image('01-conexiones.png','Plano de pines y conexiones del proyecto'), 'Reutilización del plano docs/montaje/01-conexiones.png. Señalar GPIO4 para temperatura, GPIO21/22 para I2C, GPIO18/19 para ultrasonido y GPIO27 para el botón. Las etiquetas de pines determinan las conexiones.', 'CIRCUITO','diagram')
add('Pines y alimentación', '''<table><thead><tr><th>Componente</th><th>Señales en ESP32</th><th>Alimentación / detalle</th></tr></thead><tbody>
<tr><td>DS18x20</td><td>DAT: GPIO4</td><td>3,3 V · bus 1-Wire con pull-up</td></tr>
<tr><td>MPU-6050</td><td>SDA: GPIO21 · SCL: GPIO22</td><td>3,3 V · AD0 a GND · dirección 0x68</td></tr>
<tr><td>HC-SR04</td><td>TRIG: GPIO18 · ECHO: GPIO19</td><td>5 V por VIN/USB · ECHO con divisor</td></tr>
<tr><td>Pulsador</td><td>GPIO27 y GND</td><td>INPUT_PULLUP · pulsado se lee LOW</td></tr>
</tbody></table>'''+p('<strong>Todos los módulos comparten GND.</strong> El divisor adapta ECHO antes de llegar al ESP32.'), 'Fuente: docs/montaje/MONTAJE.md y src/main.cpp. El firmware convierte LOW en botón presionado y transmite 1. El antirrebote es de 30 ms. Revisar los contactos reales del pulsador por continuidad antes de alimentar.', 'CIRCUITO')
add('Distribución en la protoboard grande',image('02-protoboard-grande.png','Contactos de alimentación y temperatura en protoboard grande'), 'Fuente: docs/montaje/02-protoboard-grande.png. G1, G2 y siguientes son grupos contados desde el extremo izquierdo según la guía, no necesariamente la numeración impresa. Se usa A–E y no se usan carriles laterales. El ESP32 y los módulos quedan fuera de las rejillas.', 'CIRCUITO','diagram')
add('Divisor de ECHO y pulsador',image('03-protoboard-pequena.png','Divisor resistivo y contactos del pulsador en protoboard pequeña'), 'Fuente: docs/montaje/03-protoboard-pequena.png. Dos resistencias de 2 kΩ en paralelo forman el tramo superior de 1 kΩ. R2 de 2 kΩ conecta el nodo GPIO19 a GND. Los contactos del botón deben pertenecer a lados eléctricamente distintos.', 'CIRCUITO','diagram')
add('Adaptación con cinco resistencias de 2 kΩ',cols(image('04-resistencias-2k.png','Adaptación con cinco resistencias de 2 kiloohmios'),bullets('<strong>ECHO:</strong> 2 kΩ en paralelo con 2 kΩ equivalen a 1 kΩ.','Con R2 = 2 kΩ a GND, el divisor entrega 5 × 2 / (1 + 2) ≈ <strong>3,33 V</strong>.','<strong>Temperatura:</strong> dos resistencias en serie forman un pull-up de 4 kΩ a 3,3 V.','Se conservan los 21 cables y el firmware.')), 'Fuente: docs/montaje/SOLO-2K.md y 04-resistencias-2k.png. ECHO no va directo al ESP32. El adaptador térmico puede incorporar pull-up: la guía indica cómo comprobarlo. Estos son valores nominales, la simulación digital no verifica las tolerancias ni el voltaje físico.', 'CIRCUITO','resistors')
add('El contrato de datos entre ESP32 y Java',code('DATA1,22.00,75.63,0.000,0.000,9.807,0')+'''<table><tr><th>Campo</th><th>0</th><th>1</th><th>2</th><th>3 / 4 / 5</th><th>6</th></tr><tr><td>Significado</td><td>DATA1</td><td>°C</td><td>cm</td><td>ax / ay / az en m/s²</td><td>Botón 0 / 1</td></tr></table>'''+bullets('Una línea contiene siete campos separados por comas y termina en salto de línea.','−9999 indica lectura inválida. Distancia negativa significa ausencia de eco.','En reposo, Z puede rondar 9,81 m/s² por la gravedad.'), 'Fuentes: Serial.printf en src/main.cpp y processLine en MonitorSensoresApp.java. DATA1 diferencia este protocolo de la versión anterior DATA. La línea mostrada coincide con las medidas registradas en la integración simulada.', 'COMUNICACIÓN')
add('Estructura de la aplicación Java',cols(code('''public class MonitorSensoresApp extends JFrame {
    private final JLabel temperatureValue = valueLabel("-- °C");
    private volatile SerialPort activePort;
    private volatile boolean connected;
    private final StringBuilder partialLine = new StringBuilder();
}'''),bullets('<strong>Herencia:</strong> JFrame aporta la ventana.','<strong>Encapsulación:</strong> campos y métodos privados mantienen el estado.','<strong>Composición:</strong> botones, etiquetas y paneles forman la interfaz.','<strong>Dependencia externa:</strong> jSerialComm permite usar el puerto serie.')), 'Extracto abreviado de la clase real. Explicar que final conserva la referencia, pero una JLabel sigue siendo modificable con setText. volatile facilita visibilidad entre hilos, pero no vuelve atómicas las operaciones compuestas. Los componentes Swing se deben modificar en su hilo de eventos.')
add('Interfaz gráfica y eventos',cols(code('''refreshButton.addActionListener(e -> refreshPorts());
connectButton.addActionListener(e -> connectToSelectedPort());
disconnectButton.addActionListener(e -> disconnect());
simulationButton.addActionListener(e -> connectSimulation());'''),bullets('buildUi() distribuye controles con BorderLayout y GridLayout.','Los JLabel presentan las medidas y JTextArea conserva la consola.','Cada clic ejecuta su método mediante una expresión lambda.','Los controles habilitados dependen del estado de conexión.')), 'Fuente: constructor y buildUi de MonitorSensoresApp.java. Explicar programación dirigida por eventos: el programa reacciona a clics y a datos entrantes. metricPanel reutiliza la construcción de cada indicador, valueLabel unifica el formato.')
add('Conexión USB con jSerialComm',code('''SerialPort port = selected.port;
port.setComPortParameters(115200, 8,
        SerialPort.ONE_STOP_BIT, SerialPort.NO_PARITY);
port.setComPortTimeouts(SerialPort.TIMEOUT_NONBLOCKING, 0, 0);
if (!port.openPort()) {
    // El código registra el error y termina el intento.
    return;
}''')+bullets('refreshPorts() consulta SerialPort.getCommPorts().','La configuración es 115200 baudios, 8 bits, una parada y sin paridad.','Si abre el puerto, guarda activePort y registra un listener de recepción.'), 'Fuente: connectToSelectedPort y refreshPorts. Fragmento abreviado con comentario explicativo. El firmware usa la misma velocidad. Cerrar otros monitores serie para evitar que ocupen el puerto. PortOption conserva el objeto SerialPort y su nombre, y sobreescribe toString para mostrar una descripción útil en el JComboBox.')
add('Recepción: reconstruir líneas completas',code('''for (byte b : bytes) {
    char c = (char) (b & 0xFF);
    if (c == '\\n') {
        String line = partialLine.toString().trim();
        partialLine.setLength(0);
        if (!line.isEmpty()) processLine(line);
    } else if (c != '\\r' && partialLine.length() < 512) {
        partialLine.append(c);
    } else if (partialLine.length() >= 512) {
        partialLine.setLength(0);
    }
}''')+p('Un evento puede traer media muestra o varias muestras. StringBuilder conserva el fragmento hasta encontrar \\n.'), 'Fuente: serialEvent dentro de connectToSelectedPort. El bucle está dentro de synchronized(partialLine). b & 0xFF interpreta el byte sin signo. El protocolo usa caracteres ASCII, por lo que este tratamiento basta para sus campos. El límite de 512 evita crecimiento indefinido de una línea sin terminador. Esta lógica acumula fragmentos y separa varias líneas recibidas juntas.',cls='widecode')
add('processLine(): validar y convertir',code(snippet('        String[] fields = line.split', '            SwingUtilities.invokeLater'))+bullets('La cabecera y el número de campos filtran mensajes ajenos a DATA1.','Double.parseDouble convierte medidas e Integer.parseInt interpreta el botón.','NumberFormatException deja un diagnóstico en la consola sin cerrar la aplicación.'), 'Fuente: processLine. El fragmento termina antes de actualizar Swing y muestra el inicio del bloque try. La comprobación de formato no valida todos los rangos físicos ni exige que el botón sea exclusivamente 0 o 1: el programa interpreta exactamente 1 como pulsado. Presentarlo como validación del formato, no como validación exhaustiva.',cls='widecode')
add('Hilos: actualización segura de Swing',code('''SwingUtilities.invokeLater(() -> {
    temperatureValue.setText(formatValue(temperature, " °C"));
    if (distance < 0) distanceValue.setText("Sin eco");
    else distanceValue.setText(formatValue(distance, " cm"));
    axValue.setText(formatValue(ax, ""));
    ayValue.setText(formatValue(ay, ""));
    azValue.setText(formatValue(az, ""));
    buttonValue.setText(pressed ? "PULSADO" : "LIBRE");
});''')+p('La recepción ocurre fuera del hilo gráfico. invokeLater agenda los cambios en el Event Dispatch Thread (EDT).'), 'Fuente: processLine y main. También main crea la ventana mediante invokeLater. Explicar que bloquear el EDT con lecturas impediría responder a los clics o repintar. Cada eje usa su propia variable, evitando repetir accidentalmente la misma lectura.',cls='widecode')
add('Errores de sensores y formato visible',code(snippet('    private static String formatValue', '    private void appendConsole'))+bullets('Los valores no finitos o menores o iguales a −1000 aparecen como “--”.','Las medidas válidas muestran dos decimales con Locale.US.','La distancia negativa tiene su propio mensaje: “Sin eco”.','appendConsole() limita el historial cuando supera 500 líneas.'), 'Fuente: formatValue, processLine y appendConsole. La comparación <= -1000 detecta el centinela -9999 y otros valores fuera de ese umbral. El formato usa punto decimal para ser consistente. El historial elimina las primeras 101 líneas al superar el límite, según getLineEndOffset(100). No se añade ninguna persistencia en disco.')
add('Simulación: TCP sin bloquear la ventana',code('''socket.connect(new java.net.InetSocketAddress("127.0.0.1", 4001), 3000);
try (BufferedReader input = new BufferedReader(
        new InputStreamReader(socket.getInputStream(), StandardCharsets.UTF_8))) {
    String line;
    while ((line = input.readLine()) != null) processLine(line);
}''')+bullets('Wokwi expone RFC2217 en 4000 y bridge.py lo adapta a TCP en 4001.','connectSimulation() realiza la lectura en el hilo wokwi-reader.','Ambas rutas reutilizan processLine(), así la interpretación es la misma.'), 'Fuente: connectSimulation, scripts/bridge.py y README.md. El fragmento está dentro de un Thread daemon con try/catch/finally. El timeout de 3000 ms se aplica a la conexión, no a todas las lecturas posteriores. El puente escucha solo en 127.0.0.1 y admite un monitor conectado.')
add('Desconexión y liberación de recursos',cols(code('''connectionGeneration++;
try {
    if (simulationSocket != null) simulationSocket.close();
} catch (Exception ignored) { }
simulationSocket = null;
SerialPort port = activePort;
connected = false;
activePort = null;'''),bullets('disconnect() cierra el socket o el puerto serie y retira su listener.','Restaura botones y estado “Desconectado”.','Al cerrar la ventana se llama disconnect() antes de dispose().','connectionGeneration permite ignorar el cierre tardío de un intento TCP anterior.')), 'Fuente: disconnect, constructor y finally de connectSimulation. Extracto inicial de disconnect. El finally compara connectionGeneration con attempt antes de programar la desconexión. Explicar la importancia de cerrar recursos para permitir futuras conexiones y la carga del firmware.')
add('Pruebas y estado real del proyecto', '''<table><thead><tr><th>Comprobación documentada</th><th>Resultado</th></tr></thead><tbody><tr><td>Compilación de firmware y Java</td><td>Correcta · Java con compatibilidad 17</td></tr><tr><td>MonitorSmokeTest</td><td>Medidas, ejes independientes, botón y datos inválidos</td></tr><tr><td>Integración Wokwi hasta Swing</td><td>Lecturas recibidas y etiquetas comprobadas por programa</td></tr><tr><td>ESP32 físico aislado · 21/10/2026</td><td>Firmware cargado y tres líneas DATA1 recibidas</td></tr><tr><td>Sensores físicos conectados</td><td>Pendiente de reconexión y prueba</td></tr></tbody></table>'''+p('La prueba de la placa aislada confirma comunicación serie. La validación del circuito físico completo sigue pendiente.'), 'Fuentes: VALIDACION.md, README.md y MonitorSmokeTest.java. Son resultados previamente documentados, no pruebas nuevas ejecutadas al crear esta presentación. La prueba de integración revisó etiquetas por programa, sin inspección visual de la ventana. El escenario Wokwi comprobó temperatura 22 a 35 °C, aceleración X y pulsador.', 'VERIFICACIÓN')
add('Demostración y aporte de Java',cols(bullets('Iniciar Wokwi y ejecutar scripts/bridge.py.','Abrir scripts/monitor.ps1 y pulsar Wokwi.','Cambiar temperatura o pulsador y observar etiquetas y consola.','Desconectar desde la interfaz y mostrar la recuperación de los controles.'),p('<strong>Qué demuestra el código</strong>')+p('Programación orientada a objetos, eventos, conversión de datos, excepciones y coordinación de hilos aplicadas a un circuito.')), 'Para USB real se selecciona el COM y se pulsa Conectar, sin puente Python. No presentar sensores físicos como probados mientras siga pendiente la prueba completa. Cerrar recordando que el circuito produce datos y Java les da estructura y una interfaz comprensible. Si se pierde conexión con Wokwi, revisar que el simulador esté activo y el puente iniciado.', 'CIERRE')

css='''*{box-sizing:border-box}body{margin:0;background:#0b1423;color:#142139;font-family:Segoe UI,Arial,sans-serif}.slide{display:none;width:100vw;height:100vh;background:#f5f4ef;padding:5vh 6vw 7vh;overflow:hidden}.slide.active{display:flex;flex-direction:column}.eyebrow{color:#087d80;font-size:clamp(12px,1.25vw,20px);font-weight:700;letter-spacing:.14em}h1{font-size:clamp(28px,3.2vw,52px);line-height:1.12;margin:2vh 0 3vh;white-space:pre-line;letter-spacing:-.025em}p,li{font-size:clamp(18px,1.8vw,29px);line-height:1.45}p{margin:1.5vh 0}ul{margin:0;padding-left:1.3em}li{margin-bottom:2vh}strong{color:#087d80}.body{flex:1;min-height:0}pre{background:#15243b;color:#f4f3eb;border-left:5px solid #26b9ac;padding:2.4vh 2vw;margin:0 0 2.5vh;white-space:pre-wrap;overflow-wrap:anywhere;font:clamp(14px,1.5vw,24px)/1.45 Consolas,monospace;tab-size:4}.widecode pre{font-size:clamp(13px,1.4vw,22px);line-height:1.36}.cols{display:grid;grid-template-columns:1.2fr 1fr;gap:4vw;height:100%;align-items:center}.cols>div{min-width:0}.cols pre{font-size:clamp(13px,1.3vw,21px)}img{display:block;max-width:100%;max-height:100%;object-fit:contain;margin:auto}.diagram .body{display:flex;justify-content:center;align-items:center}.diagram img{height:100%;width:100%}.resistors .cols{grid-template-columns:1.1fr 1fr}.resistors img{max-height:65vh}.resistors li{font-size:clamp(16px,1.55vw,25px)}table{border-collapse:collapse;width:100%;margin:2vh 0;font-size:clamp(15px,1.6vw,25px);line-height:1.4}td,th{text-align:left;padding:1.6vh 1vw;border-bottom:1px solid #c4cbc9}th{color:#087d80;font-weight:700}.big{font-size:16vw;line-height:1;color:#087d80;font-weight:700}.cover{background:#15243b;color:#f5f4ef;justify-content:center}.cover .body{flex:none}.cover h1{font-size:clamp(40px,5.7vw,90px);max-width:85%;margin:4vh 0}.cover strong,.cover .eyebrow{color:#61ded0}footer{position:absolute;bottom:2vh;left:6vw;right:6vw;display:flex;justify-content:space-between;font-size:13px;color:#657783}nav{position:fixed;bottom:1.4vh;right:2vw;z-index:5;display:flex;gap:6px}button{background:#087d80;color:white;border:0;padding:9px 12px;cursor:pointer;font:14px Segoe UI}#notes{display:none;position:fixed;inset:auto 4vw 8vh;background:#fff4ce;color:#142139;padding:20px 28px;box-shadow:0 5px 40px #0006;z-index:6;font-size:20px;line-height:1.5;max-height:42vh;overflow:auto}.hint{position:fixed;bottom:1.6vh;left:6vw;font-size:12px;color:#657783}.show-notes #notes{display:block}@media print{@page{size:landscape;margin:0}body{background:white}.slide,.slide.active{display:flex;width:297mm;height:210mm;break-after:page;padding:12mm 16mm 14mm;position:relative}h1{font-size:30pt}p,li{font-size:17pt}pre,.widecode pre{font-size:12pt}.cols pre{font-size:11pt}table{font-size:14pt}.cover h1{font-size:48pt}.diagram img{height:150mm}.resistors img{max-height:145mm}.resistors li{font-size:15pt}nav,.hint,#notes{display:none!important}footer{bottom:5mm}.slide:last-of-type{break-after:auto}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}'''
parts=[]
for i,(title,body,notes,section,cls) in enumerate(slides):
    parts.append(f'<section class="slide {cls}{" active" if i==0 else ""}" data-note="{esc(notes)}"><div class="eyebrow">{section}</div><h1>{esc(title)}</h1><div class="body">{body}</div><footer><span>MONITOR ESP32 · JAVA SWING</span><span>{i+1:02d} / {len(slides):02d}</span></footer></section>')
script='''const slides=[...document.querySelectorAll('.slide')];let current=0;const notes=document.getElementById('notes');function show(n){current=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>s.classList.toggle('active',i===current));notes.textContent=slides[current].dataset.note;location.hash=String(current+1)}function move(n){show(current+n)}document.addEventListener('keydown',e=>{if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();move(1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();move(-1)}if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1);if(e.key.toLowerCase()==='n')document.body.classList.toggle('show-notes');if(e.key.toLowerCase()==='f')full()});function full(){if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen().catch(()=>{})}show((parseInt(location.hash.slice(1))||1)-1);'''
document='<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Monitor ESP32 y Java Swing — Presentación</title><style>'+css+'</style></head><body>'+''.join(parts)+'''<aside id="notes" role="note"></aside><nav aria-label="Controles de presentación"><button onclick="move(-1)" aria-label="Anterior">←</button><button onclick="move(1)" aria-label="Siguiente">→</button><button onclick="document.body.classList.toggle('show-notes')">Notas (N)</button><button onclick="full()">Pantalla completa (F)</button><button onclick="window.print()">PDF / Imprimir</button></nav><script>'''+script+'</script></body></html>'
(OUT/'index.html').write_text(document,encoding='utf-8')
guide=['# Guion de exposición: ESP32 y Java Swing','', 'La presentación contiene 19 diapositivas. Duración orientativa: 15–20 minutos. Abre index.html, navega con las flechas y usa N para consultar las notas. F activa pantalla completa. El botón PDF / Imprimir permite guardar las diapositivas desde el navegador; elige orientación horizontal, gráficos de fondo y sin encabezados ni pies de página. Las imágenes están incorporadas: el HTML funciona sin conexión.','']
for i,(title,body,notes,section,cls) in enumerate(slides): guide += [f'## {i+1}. {title.replace(chr(10)," ")}', '',notes,'']
guide += ['## Fuentes locales','','- `src/main.cpp`','- `java-swing/src/main/java/com/ejemplo/monitor/MonitorSensoresApp.java`','- `java-swing/src/test/java/com/ejemplo/monitor/MonitorSmokeTest.java`','- `docs/montaje/MONTAJE.md` y `SOLO-2K.md`','- Planos `docs/montaje/01-conexiones.png` a `04-resistencias-2k.png`','- `README.md` y `VALIDACION.md`','', 'Los fragmentos de código conservan el comportamiento del original; algunas diapositivas omiten líneas para facilitar la explicación. Los resultados de pruebas corresponden al estado documentado del proyecto al 21 de octubre de 2026.']
(OUT/'GUION.md').write_text('\n'.join(guide),encoding='utf-8')
assert len(slides)==19
assert len(re.findall('<section ',document))==19
assert document.count('data:image/png;base64,')==4
print(f'Generadas {len(slides)} diapositivas en {OUT / "index.html"}')
